class Solution {
  private long[] bit;
  private int size;

  private void add(int i, int d) {
    for (; i <= size; i += i & -i) bit[i] += d;
  }

  private long prefix(int i) {
    long s = 0;
    for (; i > 0; i -= i & -i) s += bit[i];
    return s;
  }

  public long minInversionCount(int[] nums, int k) {
    int n = nums.length;
    int[] sorted = nums.clone();
    java.util.Arrays.sort(sorted);
    int m = 0;
    for (int i = 0; i < n; i++) if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
    int[] rank = new int[n];
    for (int i = 0; i < n; i++) rank[i] = java.util.Arrays.binarySearch(sorted, 0, m, nums[i]) + 1;
    size = m;
    bit = new long[m + 1];
    long inv = 0, best = Long.MAX_VALUE;
    int inWindow = 0;
    for (int i = 0; i < n; i++) {
      if (i >= k) {
        add(rank[i - k], -1);
        inWindow--;
        inv -= prefix(rank[i - k] - 1);
      }
      inv += inWindow - prefix(rank[i]);
      add(rank[i], 1);
      inWindow++;
      if (i >= k - 1) best = Math.min(best, inv);
    }
    return best;
  }
}
